namespace WorshipLoopStudio.Core.Samples;

/// <summary>
/// Procedural synthesis of the starter percussion library. Every sound is generated by this code,
/// so the resulting WAV files are original works covered by the repository license (no third-party recordings).
/// </summary>
public static class PercussionSynth
{
    public const int SampleRate = 44100;
    private const double TwoPi = Math.PI * 2;

    private static readonly double[] MembraneRatios = { 1.0, 1.594, 2.136, 2.296, 2.653, 2.918 };

    private static double[] NewBuffer(double seconds) => new double[(int)(seconds * SampleRate)];

    private static double T(int i) => i / (double)SampleRate;

    // ---------- Drum kit ----------

    public static float[] Kick(double startHz = 150, double endHz = 48, double decay = 0.45, double length = 0.8, uint seed = 1)
    {
        var b = NewBuffer(length);
        var noise = new NoiseSource(seed);
        var lp = Biquad.LowPass(SampleRate, 3500, 0.7);
        double phase = 0;
        for (var i = 0; i < b.Length; i++)
        {
            var t = T(i);
            var f = endHz + (startHz - endHz) * Math.Exp(-t / 0.045);
            phase += TwoPi * f / SampleRate;
            var body = Math.Sin(phase) * Math.Exp(-t / decay);
            var click = lp.Process(noise.Next()) * Math.Exp(-t / 0.004) * 0.35;
            b[i] = Math.Tanh((body + click) * 1.6);
        }

        return Finish(b);
    }

    public static float[] Snare(uint seed = 2)
    {
        var b = NewBuffer(0.45);
        var noise = new NoiseSource(seed);
        var hp = Biquad.HighPass(SampleRate, 1200, 0.7);
        var lp = Biquad.LowPass(SampleRate, 9000, 0.7);
        for (var i = 0; i < b.Length; i++)
        {
            var t = T(i);
            var tone = Math.Sin(TwoPi * 185 * t) * 0.55 * Math.Exp(-t / 0.07)
                       + Math.Sin(TwoPi * 330 * t) * 0.3 * Math.Exp(-t / 0.05);
            var wires = lp.Process(hp.Process(noise.Next())) * 0.9 * Math.Exp(-t / 0.16);
            b[i] = tone + wires;
        }

        return Finish(b);
    }

    public static float[] Clap(uint seed = 3)
    {
        var b = NewBuffer(0.5);
        var noise = new NoiseSource(seed);
        var bp1 = Biquad.BandPass(SampleRate, 1150, 1.2);
        var bp2 = Biquad.BandPass(SampleRate, 2400, 1.0);
        double[] bursts = { 0.0, 0.011, 0.022, 0.033 };
        for (var i = 0; i < b.Length; i++)
        {
            var t = T(i);
            double env = 0;
            foreach (var start in bursts)
            {
                if (t >= start)
                {
                    env += Math.Exp(-(t - start) / 0.006);
                }
            }

            if (t >= bursts[^1])
            {
                env += 0.6 * Math.Exp(-(t - bursts[^1]) / 0.12);
            }

            var n = noise.Next();
            b[i] = (bp1.Process(n) + 0.6 * bp2.Process(n)) * env;
        }

        return Finish(b);
    }

    public static float[] Rim(uint seed = 4)
    {
        var b = NewBuffer(0.15);
        var noise = new NoiseSource(seed);
        var bp = Biquad.BandPass(SampleRate, 3000, 1.0);
        for (var i = 0; i < b.Length; i++)
        {
            var t = T(i);
            b[i] = Math.Sin(TwoPi * 1750 * t) * 0.6 * Math.Exp(-t / 0.012)
                   + Math.Sin(TwoPi * 520 * t) * 0.4 * Math.Exp(-t / 0.02)
                   + bp.Process(noise.Next()) * 0.8 * Math.Exp(-t / 0.006);
        }

        return Finish(b);
    }

    public static float[] Tom(double startHz, double endHz, uint seed)
    {
        double Pitch(double t) => endHz + (startHz - endHz) * Math.Exp(-t / 0.06);
        return Membrane(Pitch, new[] { 1.0, 0.35, 0.15, 0.08, 0.05, 0.03 }, new[] { 0.35, 0.15, 0.1, 0.07, 0.05, 0.04 },
            0.8, 0.3, 0.005, 1500, seed);
    }

    // ---------- Cymbals and hi-hats ----------

    private static double[] Metal(double length, double decay, double freqMul, double highPassHz, double noiseMix, double attack, uint seed)
    {
        double[] freqs = { 205.3, 304.4, 369.6, 522.7, 540.0, 800.0 };
        var phases = new double[freqs.Length];
        var b = NewBuffer(length);
        var noise = new NoiseSource(seed);
        var hp1 = Biquad.HighPass(SampleRate, highPassHz, 0.7);
        var hp2 = Biquad.HighPass(SampleRate, highPassHz, 0.7);
        for (var i = 0; i < b.Length; i++)
        {
            var t = T(i);
            double s = 0;
            for (var k = 0; k < freqs.Length; k++)
            {
                phases[k] += freqs[k] * freqMul / SampleRate;
                phases[k] -= Math.Floor(phases[k]);
                s += phases[k] < 0.5 ? 1 : -1;
            }

            var x = s / freqs.Length * (1 - noiseMix) + noise.Next() * noiseMix;
            var env = (t < attack ? t / attack : 1.0) * Math.Exp(-t / decay);
            b[i] = hp2.Process(hp1.Process(x)) * env;
        }

        return b;
    }

    public static float[] HiHatClosed() => Finish(Metal(0.25, 0.04, 1.0, 7000, 0.25, 0.0005, 5));

    public static float[] HiHatOpen() => Finish(Metal(1.0, 0.32, 1.0, 7000, 0.25, 0.0005, 6));

    public static float[] Crash() => Finish(Metal(3.0, 1.3, 1.45, 4500, 0.5, 0.002, 7));

    public static float[] Ride()
    {
        var b = Metal(2.4, 1.1, 1.9, 5500, 0.2, 0.001, 8);
        for (var i = 0; i < b.Length; i++)
        {
            var t = T(i);
            b[i] += Math.Sin(TwoPi * 3100 * t) * 0.15 * Math.Exp(-t / 0.9)
                    + Math.Sin(TwoPi * 4650 * t) * 0.1 * Math.Exp(-t / 0.6);
        }

        return Finish(b);
    }

    // ---------- Shakers ----------

    public static float[] Shaker(double length = 0.25, double decay = 0.045, uint seed = 9)
    {
        var b = NewBuffer(length);
        var noise = new NoiseSource(seed);
        var bp = Biquad.BandPass(SampleRate, 6500, 1.4);
        const double attack = 0.015;
        for (var i = 0; i < b.Length; i++)
        {
            var t = T(i);
            var env = t < attack ? t / attack : Math.Exp(-(t - attack) / decay);
            b[i] = bp.Process(noise.Next()) * env;
        }

        return Finish(b);
    }

    /// <summary>Shekere: many bead impacts on a gourd, plus the hollow body of the gourd.</summary>
    public static float[] Shekere(uint seed = 10)
    {
        var b = NewBuffer(0.4);
        var noise = new NoiseSource(seed);
        var rng = new NoiseSource(seed * 7919);
        var env = new double[b.Length];
        for (var g = 0; g < 60; g++)
        {
            var start = (int)(Math.Pow(rng.NextUnit(), 1.5) * 0.09 * SampleRate);
            var amp = 0.3 + 0.7 * rng.NextUnit();
            var end = Math.Min(env.Length, start + (int)(0.03 * SampleRate));
            for (var i = start; i < end; i++)
            {
                env[i] += amp * Math.Exp(-(i - start) / (0.0035 * SampleRate));
            }
        }

        var bp = Biquad.BandPass(SampleRate, 3800, 0.8);
        var hp = Biquad.HighPass(SampleRate, 1500, 0.7);
        for (var i = 0; i < b.Length; i++)
        {
            var t = T(i);
            var beads = hp.Process(bp.Process(noise.Next())) * env[i] * Math.Exp(-t / 0.12);
            var gourd = Math.Sin(TwoPi * 170 * t) * Math.Exp(-t / 0.06) * 0.35;
            b[i] = beads + gourd;
        }

        return Finish(b);
    }

    // ---------- African membranes ----------

    private static float[] Membrane(Func<double, double> pitch, double[] amps, double[] decays, double length,
        double attackNoise, double noiseDecay, double noiseHz, uint seed, double decayScale = 1.0)
    {
        var b = NewBuffer(length);
        var phases = new double[MembraneRatios.Length];
        var noise = new NoiseSource(seed);
        var bp = Biquad.BandPass(SampleRate, noiseHz, 0.9);
        for (var i = 0; i < b.Length; i++)
        {
            var t = T(i);
            var f = pitch(t);
            double s = 0;
            for (var m = 0; m < MembraneRatios.Length; m++)
            {
                phases[m] += TwoPi * f * MembraneRatios[m] / SampleRate;
                s += Math.Sin(phases[m]) * amps[m] * Math.Exp(-t / (decays[m] * decayScale));
            }

            s *= Math.Min(1.0, t / 0.0015);
            s += bp.Process(noise.Next()) * attackNoise * Math.Exp(-t / noiseDecay);
            b[i] = s;
        }

        return Finish(b);
    }

    public static float[] DjembeBass() => Membrane(_ => 72, new[] { 1.0, 0.25, 0.1, 0.06, 0.04, 0.02 },
        new[] { 0.32, 0.12, 0.08, 0.06, 0.05, 0.04 }, 0.7, 0.25, 0.01, 800, 11);

    public static float[] DjembeTone() => Membrane(t => 305 + 15 * Math.Exp(-t / 0.03), new[] { 1.0, 0.6, 0.4, 0.3, 0.2, 0.12 },
        new[] { 0.2, 0.12, 0.09, 0.07, 0.06, 0.05 }, 0.5, 0.4, 0.006, 1800, 12);

    public static float[] DjembeSlap() => Membrane(_ => 400, new[] { 0.6, 0.7, 0.6, 0.5, 0.4, 0.35 },
        new[] { 0.08, 0.06, 0.05, 0.045, 0.04, 0.035 }, 0.35, 1.2, 0.02, 3200, 13);

    private static readonly double[] GanganAmps = { 1.0, 0.45, 0.25, 0.15, 0.08, 0.05 };
    private static readonly double[] GanganDecays = { 0.42, 0.2, 0.12, 0.09, 0.07, 0.05 };

    /// <summary>Yoruba gangan (talking drum). Pitch glides imitate squeezing the tension cords.</summary>
    public static float[] Gangan(double startHz, double endHz, double glideTau, double length = 0.9, double decayScale = 1.0, uint seed = 14)
    {
        double Pitch(double t) => startHz + (endHz - startHz) * (1 - Math.Exp(-t / glideTau));
        return Membrane(Pitch, GanganAmps, GanganDecays, length, 0.3, 0.006, 2200, seed, decayScale);
    }

    // ---------- Bells and gongs ----------

    private static float[] Bell(double baseHz, double[] ratios, double[] amps, double[] decays, double length, uint seed)
    {
        var b = NewBuffer(length);
        var noise = new NoiseSource(seed);
        var strike = Biquad.BandPass(SampleRate, baseHz * 3, 1.5);
        for (var i = 0; i < b.Length; i++)
        {
            var t = T(i);
            double s = 0;
            for (var k = 0; k < ratios.Length; k++)
            {
                var env = amps[k] * Math.Exp(-t / decays[k]);
                s += Math.Sin(TwoPi * baseHz * ratios[k] * t) * env;
                s += Math.Sin(TwoPi * baseHz * ratios[k] * 1.0035 * t) * env * 0.5;
            }

            s *= Math.Min(1.0, t / 0.0008);
            s += strike.Process(noise.Next()) * Math.Exp(-t / 0.003) * 0.6;
            b[i] = s;
        }

        return Finish(b);
    }

    public static float[] Agogo(double baseHz, uint seed) => Bell(baseHz, new[] { 1.0, 2.71, 4.53, 6.2 },
        new[] { 1.0, 0.45, 0.22, 0.1 }, new[] { 0.38, 0.16, 0.08, 0.05 }, 0.8, seed);

    /// <summary>Double iron bell in the style of the gankogui / ogene.</summary>
    public static float[] AfricanBell(double baseHz, uint seed) => Bell(baseHz, new[] { 1.0, 2.32, 3.86, 5.09 },
        new[] { 1.0, 0.55, 0.3, 0.15 }, new[] { 0.65, 0.3, 0.15, 0.09 }, 1.2, seed);

    public static float[] Gong(double baseHz, double decayScale, double length, uint seed)
    {
        double[] ratios = { 1, 1.47, 2.09, 2.56, 3.14, 3.76, 4.42, 5.4 };
        double[] amps = { 1, 0.75, 0.6, 0.5, 0.4, 0.3, 0.22, 0.15 };
        double[] decays = { 5.0, 4.2, 3.6, 3.0, 2.5, 2.0, 1.6, 1.2 };
        var b = NewBuffer(length);
        var noise = new NoiseSource(seed);
        var lp = Biquad.LowPass(SampleRate, 1200, 0.7);
        for (var i = 0; i < b.Length; i++)
        {
            var t = T(i);
            double s = 0;
            for (var k = 0; k < ratios.Length; k++)
            {
                var bloom = k >= 3 ? 1 - 0.5 * Math.Exp(-t / 0.25) : 1.0;
                var env = amps[k] * bloom * Math.Exp(-t / (decays[k] * decayScale));
                s += Math.Sin(TwoPi * baseHz * ratios[k] * t) * env;
                s += Math.Sin(TwoPi * baseHz * ratios[k] * 1.003 * t + 0.7) * env * 0.6;
            }

            s *= Math.Min(1.0, t / 0.012);
            s += Math.Sin(TwoPi * 55 * t) * Math.Exp(-t / 0.12) * 0.5;
            s += lp.Process(noise.Next()) * Math.Exp(-t / 0.01) * 0.3;
            b[i] = s;
        }

        return Finish(b);
    }

    /// <summary>Normalizes to -1 dBFS and fades the tail so every sample ends in silence.</summary>
    private static float[] Finish(double[] buffer, double peakTarget = 0.89, double fadeOutMs = 8)
    {
        double max = 0;
        foreach (var v in buffer)
        {
            var a = Math.Abs(v);
            if (a > max) max = a;
        }

        var scale = max > 1e-9 ? peakTarget / max : 0;
        var fade = Math.Min(buffer.Length, (int)(fadeOutMs / 1000 * SampleRate));
        var result = new float[buffer.Length];
        for (var i = 0; i < buffer.Length; i++)
        {
            var g = scale;
            var fromEnd = buffer.Length - 1 - i;
            if (fromEnd < fade)
            {
                g *= fromEnd / (double)fade;
            }

            result[i] = (float)(buffer[i] * g);
        }

        return result;
    }
}
